/*
FILE : UiText.cpp
PROJECT : Omni360
DESCRIPTION : XUI-backed implementation of the UI's text renderer. See
              UiText.h for why this replaced ATG::Font.
*/

#include "stdafx.h"
#include <xtl.h>
#include <xui.h>
#include "FontData.h"    // generated by tools/make_font_data.py
#include <xuirender.h>
#include <xuielement.h>
#include <xuierror.h>
#include <d3dx9math.h>
#include <stdio.h> // swprintf_s, for the section:// locator
#include <math.h>  // fabsf

#include "UiText.h"
#include "AtgConsole.h"
#include "OutputConsole.h"

// Deliberately NOT "using namespace ATG". The XDK declares D3DDevice at
// global scope and ATG forward-declares it inside its namespace; pulling ATG
// in wholesale makes every unqualified use ambiguous (C2872).

// The TrueType file, embedded in the XEX itself as the "selawk" section (see
// AdditionalSections in XboxTLS2.vcxproj), so Omni360 stays a single file to
// deploy. It is embedded byte for byte, not converted, so the font is still
// the font - the SIL OFL allows exactly this kind of bundling, provided the
// licence goes with it, which it does as the "ofl" section.
//
// XUI reads XEX sections through its section:// transport, addressed as
// section://<module handle in hex>,<section name> - the form the XDK's own
// AtgXime uses. The locator is built at runtime because the handle is only
// known then.
//
// A selawk.ttf beside the XEX is the fallback if the section is missing, e.g.
// from a build made without it. Locators are URIs, not Win32 paths: XUI
// requires a scheme and forward slashes, and rejects anything else with
// XUI_ERR_RESOURCE_LOCATOR_MUST_BE_ABSOLUTE.
#define UITEXT_TYPEFACE_SECTION   "selawk"
#define UITEXT_TYPEFACE_FILE_URI  L"file://game:/selawk.ttf"
#define UITEXT_TYPEFACE_NAME  L"Selawik"

// Every other typeface - Selawik's bold, and both of Open Sans's weights - is
// a separate file, so a separate typeface as far as XUI is concerned,
// registered under its own name.
//
// Not more XEX sections like the regular face. With a fourth, the XEX never
// reached main() on hardware - not a line logged - and taking it out fixed
// it. So they're compiled in as data instead (FontData.h) and written out
// beside the XEX for XUI to load as files.
struct FaceFile
{
    LPCWSTR name;               // what XUI knows it as
    const char *file;           // beside the XEX
    const unsigned char *data;  // what goes in it
    unsigned long size;
};

struct FaceInfo
{
    FaceFile regular;           // file NULL: the "selawk" section, registered in Create
    FaceFile bold;
    // On top of matching Selawik's capitals: Open Sans is a little wider than
    // Selawik, and the layout's widths were set against Selawik's.
    float tighten;
};

static const FaceInfo kFaces[UI_FACE_COUNT] =
{
    // UI_FACE_SELAWIK
    { { UITEXT_TYPEFACE_NAME, NULL, NULL, 0 },
      { L"Selawik Bold", "selawkb.ttf", kSelawikBoldTtf, kSelawikBoldTtfSize },
      1.0f },
    // UI_FACE_OPEN_SANS: SemiBold for bold, the Series dashboard's weight.
    { { L"Open Sans", "opensans.ttf", kOpenSansTtf, kOpenSansTtfSize },
      { L"Open Sans SemiBold", "opensanssb.ttf", kOpenSansSemiBoldTtf, kOpenSansSemiBoldTtfSize },
      0.97f },
    // UI_FACE_SPACE_GROTESK: as wide again as Open Sans, so tightened as much.
    { { L"Space Grotesk", "spacegrotesk.ttf", kSpaceGroteskTtf, kSpaceGroteskTtfSize },
      { L"Space Grotesk Bold", "spacegroteskb.ttf", kSpaceGroteskBoldTtf, kSpaceGroteskBoldTtfSize },
      0.96f },
};

// What became of each face: whether it's registered, and how it's sized and
// placed to stand in for Selawik.
struct FaceState
{
    bool tried;           // LoadFace has run for it
    bool loaded;          // regular registered: the face can be drawn
    bool boldLoaded;      // false draws its bold in its regular
    float scale;          // on its point size, so its capitals are Selawik's height
    float dyPerPoint;     // pixels down, per point asked for, so its capitals sit where Selawik's do
};

static FaceState g_faceState[UI_FACE_COUNT];

// Selawik's capitals at the reference size, which every face is matched to.
static float g_selawikCap = 0.0f;
static float g_selawikCapMid = 0.0f;

// The text height the layout is written against. Every SetScaleFactors value
// in the UI is a multiple of this, and GetFontHeight returns it so the
// resolution-scaling maths in ComputeUiMetrics stays a no-op.
#define UITEXT_DESIGN_PX      22.0f

// Applied on top of the calibrated point size. XUI's reported line height
// includes leading, so sizing purely by it renders glyphs slightly smaller
// than a strike height of the same number would. This is the one constant to
// turn if the type comes out uniformly too small or too large.
#define UITEXT_SIZE_TRIM      1.18f

// Distinct sizes in play are few - a dozen scale factors, some in both
// weights, and one resolution per session - so a small fixed cache covers it
// without ever evicting.
#define UITEXT_MAX_FONTS      64 // two faces' worth: the theme's and Selawik's

// The size every face is measured at, to match one to another.
#define UITEXT_REFERENCE_POINTS 20.0f

struct CachedFont
{
    float    pixels;
    bool     bold;
    int      face;
    HXUIFONT font;
};

static CachedFont g_fonts[UITEXT_MAX_FONTS];
static int        g_fontCount = 0;

static HXUIDC g_hDC = NULL;

static float g_backBufferW = 0.0f;
static float g_backBufferH = 0.0f;

// Pixels of line height per point, measured on this device at init rather
// than assumed. Points are not pixels and the ratio is a property of the
// renderer, so it is cheaper to ask once than to guess and rebuild.
static float g_pixelsPerPoint = 1.0f;

// Which init steps completed, so teardown undoes only those. A blind reverse
// teardown after a half-finished init is its own way to crash.
static bool g_renderInited   = false;
static bool g_dcCreated      = false;
static bool g_xuiInited      = false;
static bool g_typefaceLoaded = false;

UiFont::UiFont()
    : m_scale(1.0f)
    , m_bold(false)
    , m_ready(false)
    , m_face(UI_FACE_SELAWIK)
{
}

int UiFont::GetFace() const
{
    return g_faceState[m_face].loaded ? m_face : UI_FACE_SELAWIK;
}

bool UiFont::IsReady() const
{
    return m_ready;
}

float UiFont::GetFontHeight() const
{
    return UITEXT_DESIGN_PX;
}

float UiFont::SizeForScale(float scale) const
{
    float px = UITEXT_DESIGN_PX * scale;
    return (px < 1.0f) ? 1.0f : px;
}

void UiFont::SetScaleFactors(float scaleX, float /*scaleY*/)
{
    m_scale = scaleX;
}

void UiFont::SetBold(bool bold)
{
    m_bold = bold;
}

void *UiFont::FontForPixelSize(float pixels, bool bold)
{
    // Rounded before comparing so scale factors that differ only by floating
    // point noise share one font rather than each creating their own.
    float key = (float)((int)(pixels + 0.5f));

    const int face = GetFace();
    if (!g_faceState[face].boldLoaded)
        bold = false;

    for (int i = 0; i < g_fontCount; ++i)
    {
        if (g_fonts[i].pixels == key && g_fonts[i].bold == bold && g_fonts[i].face == face)
            return g_fonts[i].font;
    }

    if (g_fontCount >= UITEXT_MAX_FONTS)
    {
        // Falling back to an existing font keeps text on screen at slightly
        // the wrong size, which is far better than drawing nothing.
        dprintf("[UiText] font cache full at %d entries, reusing %.0fpx for %.0fpx\n",
                UITEXT_MAX_FONTS, g_fonts[0].pixels, key);
        return g_fontCount > 0 ? g_fonts[0].font : NULL;
    }

    float points = (key / g_pixelsPerPoint) * UITEXT_SIZE_TRIM * g_faceState[face].scale;

    const FaceInfo &info = kFaces[face];
    HXUIFONT font = NULL;
    HRESULT hr = XuiCreateFont(bold ? info.bold.name : info.regular.name, points,
                               XUI_FONT_STYLE_NORMAL, 0, &font);
    if (FAILED(hr))
    {
        dprintf("[UiText] XuiCreateFont(%S, %.1fpt for %.0fpx) -> 0x%08lX\n",
                bold ? info.bold.name : info.regular.name, points, key, (unsigned long)hr);
        return g_fontCount > 0 ? g_fonts[0].font : NULL;
    }

    g_fonts[g_fontCount].pixels = key;
    g_fonts[g_fontCount].bold = bold;
    g_fonts[g_fontCount].face = face;
    g_fonts[g_fontCount].font = font;
    g_fontCount++;

    return font;
}

// Makes sure game:\<file> is the font compiled into this XEX: written if
// it's missing or a different size, left alone otherwise, so a normal launch
// only checks its size. False if it couldn't be written.
static bool EnsureFontFile(const FaceFile &f)
{
    char path[64];
    _snprintf(path, sizeof(path), "game:\\%s", f.file);
    path[sizeof(path) - 1] = '\0';

    WIN32_FILE_ATTRIBUTE_DATA attrs;
    if (GetFileAttributesExA(path, GetFileExInfoStandard, &attrs) &&
        attrs.nFileSizeHigh == 0 && attrs.nFileSizeLow == f.size)
        return true;

    HANDLE file = CreateFileA(path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    if (file == INVALID_HANDLE_VALUE)
    {
        dprintf("[UiText] couldn't create %s (%lu)\n", path, GetLastError());
        return false;
    }

    DWORD written = 0;
    BOOL ok = WriteFile(file, f.data, f.size, &written, NULL);
    CloseHandle(file);

    if (!ok || written != f.size)
    {
        dprintf("[UiText] couldn't write %s (%lu of %lu bytes)\n", path, written, f.size);
        DeleteFileA(path);
        return false;
    }

    dprintf("[UiText] wrote %s\n", path);
    return true;
}

// One of the files beside the XEX, written out if need be and registered
// with XUI under its name.
static bool RegisterFontFile(const FaceFile &f)
{
    if (!EnsureFontFile(f))
        return false;

    WCHAR uri[64];
    swprintf_s(uri, ARRAYSIZE(uri), L"file://game:/%S", f.file);

    TypefaceDescriptor desc;
    ZeroMemory(&desc, sizeof(desc));
    desc.szTypeface = f.name;
    desc.szLocator = uri;
    desc.szReserved1 = NULL;
    desc.fBaselineAdjust = 0.0f;
    desc.szFallbackTypeface = NULL;

    HRESULT hr = XuiRegisterTypeface(&desc, FALSE);
    if (FAILED(hr))
    {
        dprintf("[UiText] %S -> 0x%08lX\n", f.name, (unsigned long)hr);
        return false;
    }

    dprintf("[UiText] typeface %S: %S\n", f.name, uri);
    return true;
}

// A face's capitals at the reference size: how tall, and how far down from
// the top of the line their middle sits. Measured on an H, where XUI puts it,
// rather than read from the file, since which of a font's ascents XUI lays a
// line out by isn't documented.
static bool MeasureCapitals(LPCWSTR name, float points, float *cap, float *mid)
{
    HXUIFONT font = NULL;
    if (FAILED(XuiCreateFont(name, points, XUI_FONT_STYLE_NORMAL, 0, &font)))
        return false;

    XUIFontMetrics fm;
    XUICharMetrics cm;
    const bool ok = SUCCEEDED(XuiGetFontMetrics(font, &fm)) && SUCCEEDED(XuiGetCharMetrics(font, L'H', &cm));
    XuiReleaseFont(font);
    if (!ok || cm.fMaxY <= cm.fMinY)
        return false;

    *cap = cm.fMaxY - cm.fMinY;
    // An H stands on the baseline: one of its ends at 0 says the metrics are
    // from the baseline, and the ascent places it; otherwise they're from the
    // line's top already.
    if (fabsf(cm.fMinY) < 0.5f || fabsf(cm.fMaxY) < 0.5f)
        *mid = fm.fMaxAscent - *cap * 0.5f;
    else
        *mid = (cm.fMinY + cm.fMaxY) * 0.5f;

    dprintf("[UiText] %S at %.0fpt: line %.2f ascent %.2f descent %.2f, H %.2f..%.2f -> cap %.2f mid %.2f\n",
            name, points, fm.fLineHeight, fm.fMaxAscent, fm.fMaxDescent, cm.fMinY, cm.fMaxY, *cap, *mid);
    return true;
}

// Registers a face, once, and matches it to Selawik: scaled so its capitals
// are as tall, then moved so their middles line up.
static void LoadFace(int face)
{
    FaceState &st = g_faceState[face];
    if (st.tried)
        return;
    st.tried = true;

    const FaceInfo &info = kFaces[face];
    if (info.regular.file != NULL && !RegisterFontFile(info.regular))
    {
        dprintf("[UiText] face %d unavailable; Selawik draws instead\n", face);
        return;
    }
    st.boldLoaded = RegisterFontFile(info.bold);

    st.scale = info.tighten;
    st.dyPerPoint = 0.0f;
    float cap = 0.0f, mid = 0.0f;
    if (face != UI_FACE_SELAWIK && g_selawikCap > 0.0f &&
        MeasureCapitals(info.regular.name, UITEXT_REFERENCE_POINTS, &cap, &mid) && cap > 0.0f)
    {
        st.scale = g_selawikCap / cap * info.tighten;
        st.dyPerPoint = (g_selawikCapMid - mid * st.scale) / UITEXT_REFERENCE_POINTS;
        dprintf("[UiText] face %d: scale %.3f, %.3f px down per point\n", face, st.scale, st.dyPerPoint);
    }
    st.loaded = true;
}

void UiFont::SetFace(int face)
{
    if (face < 0 || face >= UI_FACE_COUNT)
        face = UI_FACE_SELAWIK;
    m_face = face;
    if (m_ready)
        LoadFace(face);
}

HRESULT UiFont::Create(const char * /*ignoredLegacyPath*/)
{
    if (m_ready)
        return S_OK;

    ::D3DDevice *pDevice = ATG::Console::GetDevice();
    const D3DPRESENT_PARAMETERS *pParams = ATG::Console::GetPresentParams();

    if (pDevice == NULL || pParams == NULL)
    {
        dprintf("[UiText] no device or present params from Console\n");
        return E_FAIL;
    }

    HRESULT hr = XuiRenderInitShared(pDevice, pParams, XuiD3DXTextureLoader);
    if (FAILED(hr))
    {
        dprintf("[UiText] XuiRenderInitShared -> 0x%08lX\n", (unsigned long)hr);
        return hr;
    }
    g_renderInited = true;

    g_backBufferW = (float)pParams->BackBufferWidth;
    g_backBufferH = (float)pParams->BackBufferHeight;

    hr = XuiRenderCreateDC(&g_hDC);
    if (FAILED(hr))
    {
        dprintf("[UiText] XuiRenderCreateDC -> 0x%08lX\n", (unsigned long)hr);
        Destroy();
        return hr;
    }
    g_dcCreated = true;

    XUIInitParams initParams;
    ZeroMemory(&initParams, sizeof(initParams));
    initParams.cbSize = sizeof(initParams);
    initParams.dwFlags = 0;
    initParams.pHooks = NULL; // no scene graph here, so no runtime hooks

    hr = XuiInit(&initParams);
    if (FAILED(hr))
    {
        dprintf("[UiText] XuiInit -> 0x%08lX\n", (unsigned long)hr);
        Destroy();
        return hr;
    }
    g_xuiInited = true;

    // Prefer the copy inside the XEX. Checked with XGetModuleSection first
    // rather than inferred from XuiRegisterTypeface failing, because whether
    // registration opens the resource straight away or only when a font is
    // first created isn't documented - a failure there could surface later
    // and far from its cause.
    HANDLE hModule = GetModuleHandle(NULL);
    PVOID sectionData = NULL;
    ULONG sectionSize = 0;

    WCHAR sectionUri[64];
    LPCWSTR locator = UITEXT_TYPEFACE_FILE_URI;

    if (XGetModuleSection(hModule, UITEXT_TYPEFACE_SECTION, &sectionData, &sectionSize) && sectionSize > 0)
    {
        swprintf_s(sectionUri, ARRAYSIZE(sectionUri), L"section://%x,%S",
                   (unsigned int)(UINT_PTR)hModule, UITEXT_TYPEFACE_SECTION);
        locator = sectionUri;
        dprintf("[UiText] font: XEX section \"%s\" (%lu bytes)\n", UITEXT_TYPEFACE_SECTION, sectionSize);
    }
    else
    {
        dprintf("[UiText] font: no \"%s\" section in the XEX, trying selawk.ttf beside it\n",
                UITEXT_TYPEFACE_SECTION);
    }

    TypefaceDescriptor desc;
    ZeroMemory(&desc, sizeof(desc));
    desc.szTypeface = UITEXT_TYPEFACE_NAME;
    desc.szLocator = locator;
    desc.szReserved1 = NULL;
    desc.fBaselineAdjust = 0.0f;
    desc.szFallbackTypeface = NULL;

    hr = XuiRegisterTypeface(&desc, TRUE);
    if (FAILED(hr))
    {
        const char *why = "unrecognised - look it up in xuierror.h";

        if (hr == XUI_ERR_RESOURCE_LOCATOR_MUST_BE_ABSOLUTE)
            why = "locator is not an absolute URI - needs a scheme, e.g. file://game:/name.ttf";
        else if (hr == XUI_ERR_RESOURCE_COULD_NOT_BE_OPENED)
            why = "locator parsed, but the resource could not be opened";
        else if (hr == XUI_ERR_INVALID_RESOURCE_PATH)
            why = "resource path rejected - check the drive alias exists";
        else if (hr == XUI_ERR_FILE_INVALID)
            why = "file opened but was not a usable font";

        dprintf("[UiText] XuiRegisterTypeface(%S) -> 0x%08lX: %s\n", locator, (unsigned long)hr, why);
        Destroy();
        return hr;
    }
    g_typefaceLoaded = true;
    g_faceState[UI_FACE_SELAWIK].tried = true;
    g_faceState[UI_FACE_SELAWIK].loaded = true;
    g_faceState[UI_FACE_SELAWIK].scale = 1.0f;
    g_faceState[UI_FACE_SELAWIK].boldLoaded = RegisterFontFile(kFaces[UI_FACE_SELAWIK].bold);

    // Calibrate points to pixels on this device instead of assuming a DPI.
    // One reference font, one metrics query; every size after this is derived
    // from the ratio.
    const float REFERENCE_POINTS = 20.0f;

    HXUIFONT reference = NULL;
    hr = XuiCreateFont(UITEXT_TYPEFACE_NAME, REFERENCE_POINTS, XUI_FONT_STYLE_NORMAL, 0, &reference);
    if (FAILED(hr))
    {
        dprintf("[UiText] reference XuiCreateFont -> 0x%08lX\n", (unsigned long)hr);
        Destroy();
        return hr;
    }

    XUIFontMetrics metrics;
    if (SUCCEEDED(XuiGetFontMetrics(reference, &metrics)) && metrics.fLineHeight > 0.0f)
    {
        g_pixelsPerPoint = metrics.fLineHeight / REFERENCE_POINTS;
    }
    else
    {
        // 1:1 is wrong but survivable - text renders, just at the wrong size,
        // which is visible and fixable rather than a blank screen.
        g_pixelsPerPoint = 1.0f;
        dprintf("[UiText] font metrics unavailable, assuming 1px per point\n");
    }

    XuiReleaseFont(reference);

    dprintf("[UiText] ready: backbuffer %.0fx%.0f, %.3f px per point\n",
            g_backBufferW, g_backBufferH, g_pixelsPerPoint);

    // Selawik's capitals, for the other faces to match.
    if (!MeasureCapitals(UITEXT_TYPEFACE_NAME, UITEXT_REFERENCE_POINTS, &g_selawikCap, &g_selawikCapMid))
        g_selawikCap = 0.0f; // the others then draw at their own size, unmoved

    m_ready = true;
    LoadFace(m_face);
    return S_OK;
}

void UiFont::Begin()
{
    if (!m_ready)
        return;

    // Transparent clear: confirmed on hardware to leave the frame's existing
    // quads and any other drawing intact.
    XuiRenderBegin(g_hDC, D3DCOLOR_ARGB(0, 0, 0, 0));

    D3DXMATRIX matView;
    D3DXMatrixIdentity(&matView);
    XuiRenderSetViewTransform(g_hDC, &matView);
}

void UiFont::End()
{
    if (!m_ready)
        return;

    XuiRenderEnd(g_hDC);

    // Deliberately not XuiRenderPresent - this app presents its own frame.
}

float UiFont::GetTextWidth(const WCHAR *strText)
{
    if (!m_ready || strText == NULL)
        return 0.0f;

    HXUIFONT font = (HXUIFONT)FontForPixelSize(SizeForScale(m_scale), m_bold);
    if (font == NULL)
        return 0.0f;

    XUIRect rect;
    rect.left = 0.0f;
    rect.top = 0.0f;
    rect.right = g_backBufferW;
    rect.bottom = g_backBufferH;

    XuiMeasureText(font, strText, -1, XUI_FONT_STYLE_NORMAL, 0, &rect);

    return rect.right - rect.left;
}

// The longest start of text that fits maxWidth with "..." after it, ended at
// a word when that doesn't throw away much (a single long word is cut
// anywhere), without the space or punctuation before the dots.
void UiFont::ShortenToWidth(const WCHAR *text, float maxWidth, WCHAR *out, int outChars)
{
    static const WCHAR kDots[] = L"...";
    int length = (int)wcslen(text);
    if (length > outChars - 4)
        length = outChars - 4;

    // Binary search on the number of characters kept.
    int lo = 0, hi = length;
    while (lo < hi)
    {
        const int mid = (lo + hi + 1) / 2;
        wcsncpy(out, text, mid);
        out[mid] = L'\0';
        wcscat(out, kDots);
        if (GetTextWidth(out) <= maxWidth)
            lo = mid;
        else
            hi = mid - 1;
    }
    int keep = lo;

    // Back to the end of a word, unless the cut already falls between words
    // or the last word started more than a third of the way back.
    if (keep < length && keep > 0 && text[keep] != L' ' && text[keep - 1] != L' ')
    {
        int space = keep - 1;
        while (space > 0 && text[space] != L' ')
            space--;
        if (space > 0 && space >= keep * 2 / 3)
            keep = space;
    }
    while (keep > 0 && wcschr(L" ,;:-.\x00B7\x2013\x2014", text[keep - 1]) != NULL)
        keep--;

    wcsncpy(out, text, keep);
    out[keep] = L'\0';
    wcscat(out, kDots);
}

void UiFont::DrawText(float sx, float sy, DWORD dwColor, const WCHAR *strText,
                      DWORD dwFlags, float fMaxPixelWidth)
{
    if (!m_ready || strText == NULL || strText[0] == L'\0')
        return;

    HXUIFONT font = (HXUIFONT)FontForPixelSize(SizeForScale(m_scale), m_bold);
    if (font == NULL)
        return;

    // Single line, no wrapping: every caller here draws one line into a fixed
    // row, and letting XUI wrap would silently push text outside its row.
    DWORD style = XUI_FONT_STYLE_SINGLE_LINE | XUI_FONT_STYLE_NO_WORDWRAP;

    float width = (fMaxPixelWidth > 0.0f) ? fMaxPixelWidth : (g_backBufferW - sx);
    if (width < 1.0f)
        width = 1.0f;

    // Too long: shortened here rather than by XUI's ellipsis style, which cut
    // mid-word and drew a "…" that Selawik shows as one full stop - so
    // "Left 4 Dead 2" read as "Left 4 Dead." Ours ends at a word, with "...".
    WCHAR shortened[256];
    if ((dwFlags & UITEXT_TRUNCATED) && fMaxPixelWidth > 0.0f && GetTextWidth(strText) > fMaxPixelWidth)
    {
        ShortenToWidth(strText, fMaxPixelWidth, shortened, sizeof(shortened) / sizeof(shortened[0]));
        strText = shortened;
    }

    // Alignment is resolved by moving the draw origin rather than by handing
    // XUI an alignment flag. ATG::Font treats sx as the RIGHT edge for
    // right-aligned text, whereas XUI would align within its rect - so
    // measuring and shifting is what actually reproduces the old behaviour.
    float originX = sx;

    if (dwFlags & (UITEXT_RIGHT | UITEXT_CENTER_X))
    {
        float textW = GetTextWidth(strText);
        if (fMaxPixelWidth > 0.0f && textW > fMaxPixelWidth)
            textW = fMaxPixelWidth;

        if (dwFlags & UITEXT_RIGHT)
            originX = sx - textW;
        else
            originX = sx - textW * 0.5f;

        // A pixel spare: the measured width, exactly, can lose the last glyph.
        width = (textW > 1.0f) ? textW + 1.0f : 1.0f;
    }

    XUIRect rect;
    rect.left = 0.0f;
    rect.top = 0.0f;
    rect.right = width;
    rect.bottom = g_backBufferH - sy;
    if (rect.bottom < 1.0f)
        rect.bottom = 1.0f;

    const int face = GetFace();
    if (g_faceState[face].dyPerPoint != 0.0f)
        sy += g_faceState[face].dyPerPoint * (SizeForScale(m_scale) / g_pixelsPerPoint) * UITEXT_SIZE_TRIM;

    D3DXMATRIX matPos;
    D3DXMatrixIdentity(&matPos);
    matPos._41 = originX;
    matPos._42 = sy;
    XuiRenderSetTransform(g_hDC, &matPos);

    XuiSelectFont(g_hDC, font);
    XuiSetColorFactor(g_hDC, dwColor);

    XuiDrawText(g_hDC, strText, style, 0, &rect);
}

void UiFont::Destroy()
{
    for (int i = 0; i < g_fontCount; ++i)
    {
        if (g_fonts[i].font != NULL)
            XuiReleaseFont(g_fonts[i].font);

        g_fonts[i].font = NULL;
        g_fonts[i].pixels = 0.0f;
        g_fonts[i].bold = false;
    }
    g_fontCount = 0;

    for (int f = 0; f < UI_FACE_COUNT; ++f)
    {
        FaceState &st = g_faceState[f];
        if (st.boldLoaded)
            XuiUnregisterTypeface(kFaces[f].bold.name);
        if (st.loaded && kFaces[f].regular.file != NULL)
            XuiUnregisterTypeface(kFaces[f].regular.name);
        ZeroMemory(&st, sizeof(st));
    }

    if (g_typefaceLoaded)
    {
        XuiUnregisterTypeface(UITEXT_TYPEFACE_NAME);
        g_typefaceLoaded = false;
    }

    if (g_xuiInited)
    {
        XuiUninit();
        g_xuiInited = false;
    }

    if (g_dcCreated)
    {
        XuiRenderDestroyDC(g_hDC);
        g_hDC = NULL;
        g_dcCreated = false;
    }

    if (g_renderInited)
    {
        XuiRenderUninit();
        g_renderInited = false;
    }

    m_ready = false;
}
